CREATE TABLE public.scrapbook_owners (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE);
GRANT SELECT ON public.scrapbook_owners TO authenticated;
GRANT ALL ON public.scrapbook_owners TO service_role;
ALTER TABLE public.scrapbook_owners ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Owner reads own membership" ON public.scrapbook_owners FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.assign_scrapbook_owner() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF lower(NEW.email) = 'ssupritha2006@gmail.com' AND NEW.email_confirmed_at IS NOT NULL THEN INSERT INTO public.scrapbook_owners(user_id) VALUES(NEW.id) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.assign_scrapbook_owner() FROM PUBLIC;
CREATE TRIGGER assign_scrapbook_owner_on_auth AFTER INSERT OR UPDATE OF email_confirmed_at,email ON auth.users FOR EACH ROW EXECUTE FUNCTION public.assign_scrapbook_owner();
INSERT INTO public.scrapbook_owners(user_id) SELECT id FROM auth.users WHERE lower(email) = 'ssupritha2006@gmail.com' AND email_confirmed_at IS NOT NULL ON CONFLICT DO NOTHING;
CREATE TABLE public.scrapbook_photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, path text UNIQUE NOT NULL, caption text NOT NULL CHECK (char_length(caption) BETWEEN 1 AND 160), category text NOT NULL CHECK(category IN ('childhood','couple')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.scrapbook_photos TO authenticated;
GRANT SELECT ON public.scrapbook_photos TO anon;
GRANT ALL ON public.scrapbook_photos TO service_role;
ALTER TABLE public.scrapbook_photos ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Published scrapbook metadata" ON public.scrapbook_photos FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Owner adds photos" ON public.scrapbook_photos FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS(SELECT 1 FROM public.scrapbook_owners WHERE user_id=auth.uid()) AND path LIKE auth.uid()::text || '/%');
CREATE POLICY "Owner removes photos" ON public.scrapbook_photos FOR DELETE TO authenticated USING (user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.scrapbook_owners WHERE user_id=auth.uid()));
CREATE POLICY "Owner uploads scrapbook files" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='scrapbook-photos' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.scrapbook_owners WHERE user_id=auth.uid()));
CREATE POLICY "Owner reads scrapbook files" ON storage.objects FOR SELECT TO authenticated USING(bucket_id='scrapbook-photos' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.scrapbook_owners WHERE user_id=auth.uid()));
CREATE POLICY "Owner removes scrapbook files" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='scrapbook-photos' AND (storage.foldername(name))[1]=auth.uid()::text AND EXISTS(SELECT 1 FROM public.scrapbook_owners WHERE user_id=auth.uid()));